# Count connected components again more carefully
def get_components_and_props(grid):
    visited = set()
    components = []
    h, w = len(grid), len(grid[0])

    def dfs(r, c, comp):
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in visited:
                continue
            visited.add((cr, cc))
            comp.append((cr, cc))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] > 0 and (nr, nc) not in visited:
                    stack.append((nr, nc))

    for r in range(h):
        for c in range(w):
            if grid[r][c] > 0 and (r, c) not in visited:
                comp = []
                dfs(r, c, comp)
                # Calculate bounding box
                rows = [r_c[0] for r_c in comp]
                cols = [r_c[1] for r_c in comp]
                min_r, max_r = min(rows), max(rows)
                min_c, max_c = min(cols), max(cols)
                bbox_h = max_r - min_r + 1
                bbox_w = max_c - min_c + 1
                components.append({'cells': comp, 'bbox': ((min_r, min_c), (max_r, max_c)), 'size': len(comp), 'dim': (bbox_h, bbox_w)})

    return components

