dem2_output = G['Demo pair 2 output']

# Check if output is a subset of input (direct subgrid)
print("Checking if output appears as subgrid in input:")

def contains_subgrid(big_grid, small_grid):
    bh, bw = len(big_grid), len(big_grid[0])
    sh, sw = len(small_grid), len(small_grid[0])

    for r in range(bh - sh + 1):
        for c in range(bw - sw + 1):
            match = True
            for sr in range(sh):
                for sc in range(sw):
                    if big_grid[r+sr][c+sc] != small_grid[sr][sc]:
                        match = False
                        break
                if not match:
                    break
            if match:
                return True
    return False

