        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
test_input = G['Test input']

def find_hollow_rectangles(grid):
    """Find rectangular regions with non-zero borders and zero interiors"""
    results = []
    h, w = len(grid), len(grid[0])

    for height in range(4, 9):  # At least 4x4
        for width in range(4, 9):  # At least 4x4  
            for r in range(h - height + 1):
                for c in range(w - width + 1):
                    border_ok = True
                    interior_zeros = False

                    for rr in range(height):
                        for cc in range(width):
                            val = grid[r + rr][c + cc]
                            is_border = (rr == 0 or rr == height - 1 or cc == 0 or cc == width - 1)

                            if is_border:
                                if val == 0:
                                    border_ok = False
                            else:
                                if val == 0:
                                    interior_zeros = True

                    if border_ok and interior_zeros:
                        nnz = sum(1 for rr in range(height) for cc in range(width) 
                                  if grid[r + rr][c + cc] > 0)

                        results.append({
                            'top': (r, c),
                            'height': height,
                            'width': width,
                            'nnz': nnz,
                            'bbox': ((r,c), (r+height-1, c+width-1))
                        })

    return results

